import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result * sign
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val t = fs.nextInt()

    var dp = Array(5) { Array(3) { Array(t + 1) { LongArray(t) } } }

    for (y in 1..4) {
        dp[y][0][0][0] = 1L
    }

    repeat(n - 1) {
        val next = Array(5) { Array(3) { Array(t + 1) { LongArray(t) } } }

        for (last in 1..4) {
            for (direction in 0..2) {
                for (peaks in 0..t) {
                    for (valleys in 0 until t) {
                        val count = dp[last][direction][peaks][valleys]
                        if (count == 0L) continue

                        for (value in 1..4) {
                            if (value == last) continue

                            val newDirection = if (value > last) 1 else 2
                            var newPeaks = peaks
                            var newValleys = valleys

                            if (direction == 1 && newDirection == 2) {
                                newPeaks++
                            } else if (direction == 2 && newDirection == 1) {
                                newValleys++
                            }

                            if (newPeaks <= t && newValleys < t) {
                                next[value][newDirection][newPeaks][newValleys] += count
                            }
                        }
                    }
                }
            }
        }

        dp = next
    }

    var answer = 0L
    for (last in 1..4) {
        for (direction in 1..2) {
            answer += dp[last][direction][t][t - 1]
        }
    }

    print(answer)
}

